import { Component, OnInit } from '@angular/core';

interface Group {
  name: string;
  gradelevel: string;
  studentsCount: number;
  schedule: string;
  teacher: string;
}

@Component({
  selector: 'app-classes',
  templateUrl: './classes.component.html',
  styleUrls: ['./classes.component.css']
})
export class ClassesComponent implements OnInit {

  // =========================================================
  // Groups Data
  // =========================================================

  groups: Group[] = [
    {
      name: 'Group A',
      gradelevel: 'Grade 1',
      studentsCount: 20,
      schedule: 'Saturday - Monday 10:00 AM',
      teacher: 'Ahmed Hassan'
    },
    {
      name: 'Group B',
      gradelevel: 'Grade 2',
      studentsCount: 18,
      schedule: 'Sunday - Tuesday 12:00 PM',
      teacher: 'Mohamed Omar'
    },
    {
      name: 'Group C',
      gradelevel: 'Grade 3',
      studentsCount: 22,
      schedule: 'Monday - Wednesday 02:00 PM',
      teacher: 'Youssef Farag'
    }
  ];

  // Groups displayed after filtering
  filteredGroups: Group[] = [];

  // =========================================================
  // Filter Options
  // =========================================================

  gradeLevels: string[] = [];
  teachers: string[] = [];

  searchValue: string = '';
  selectedGradeLevel: string = '';
  selectedTeacher: string = '';

  // =========================================================
  // Modals
  // =========================================================

  isModalOpen: boolean = false;
  isDetailsModalOpen: boolean = false;

  selectedGroup: Group | null = null;

  // =========================================================
  // New / Edited Group
  // =========================================================

  newGroup = {
    name: '',
    gradelevel: '',
    studentsCount: 0,
    schedule: '',
    teacher: ''
  };

  isEditMode: boolean = false;

  // =========================================================
  // Lifecycle
  // =========================================================

  ngOnInit(): void {
    this.updateFilterOptions();
    this.filteredGroups = [...this.groups];
  }

  // =========================================================
  // Statistics
  // =========================================================

  get totalStudentsCount(): number {
    return this.groups.reduce(
      (total, group) => total + Number(group.studentsCount),
      0
    );
  }

  get gradeLevelsCount(): number {
    return new Set(
      this.groups
        .map(group => group.gradelevel)
        .filter(level => level.trim())
    ).size;
  }

  get teachersCount(): number {
    return new Set(
      this.groups
        .map(group => group.teacher)
        .filter(teacher => teacher.trim())
    ).size;
  }

  // =========================================================
  // Initials
  // =========================================================

  getInitial(name: string): string {
    if (!name) {
      return '';
    }

    return name.charAt(0).toUpperCase();
  }

  getInitials(name: string): string {
    return name
      .split(' ')
      .filter(word => word.length > 0)
      .map(word => word.charAt(0))
      .join('')
      .substring(0, 2)
      .toUpperCase();
  }

  // =========================================================
  // Filter Options
  // =========================================================

  updateFilterOptions(): void {

    this.gradeLevels = [
      ...new Set(
        this.groups
          .map(group => group.gradelevel)
          .filter(level => level.trim())
      )
    ];

    this.teachers = [
      ...new Set(
        this.groups
          .map(group => group.teacher)
          .filter(teacher => teacher.trim())
      )
    ];
  }

  // =========================================================
  // Filters
  // =========================================================

  applyFilters(): void {

    const search = this.searchValue
      .toLowerCase()
      .trim();

    this.filteredGroups = this.groups.filter(group => {

      const matchesSearch =
        !search ||
        group.name.toLowerCase().includes(search) ||
        group.gradelevel.toLowerCase().includes(search) ||
        group.teacher.toLowerCase().includes(search) ||
        group.schedule.toLowerCase().includes(search);

      const matchesGrade =
        !this.selectedGradeLevel ||
        group.gradelevel === this.selectedGradeLevel;

      const matchesTeacher =
        !this.selectedTeacher ||
        group.teacher === this.selectedTeacher;

      return (
        matchesSearch &&
        matchesGrade &&
        matchesTeacher
      );
    });
  }

  // =========================================================
  // Add Group
  // =========================================================

  onAddGroupClick(): void {

    this.isEditMode = false;
    this.selectedGroup = null;

    this.newGroup = {
      name: '',
      gradelevel: '',
      studentsCount: 0,
      schedule: '',
      teacher: ''
    };

    this.isModalOpen = true;
  }

  // =========================================================
  // Close Add / Edit Modal
  // =========================================================

  closeModal(): void {

    this.isModalOpen = false;
    this.selectedGroup = null;
    this.isEditMode = false;
  }

  // =========================================================
  // Save / Update Group
  // =========================================================

  saveGroup(): void {

    if (
      !this.newGroup.name.trim() ||
      !this.newGroup.gradelevel.trim()
    ) {
      return;
    }

    // =======================================================
    // Edit Existing Group
    // =======================================================

    if (this.isEditMode && this.selectedGroup) {

      this.selectedGroup.name =
        this.newGroup.name.trim();

      this.selectedGroup.gradelevel =
        this.newGroup.gradelevel.trim();

      this.selectedGroup.studentsCount =
        Number(this.newGroup.studentsCount);

      this.selectedGroup.schedule =
        this.newGroup.schedule.trim();

      this.selectedGroup.teacher =
        this.newGroup.teacher.trim();
    }

    // =======================================================
    // Add New Group
    // =======================================================

    else {

      const group: Group = {

        name: this.newGroup.name.trim(),

        gradelevel:
          this.newGroup.gradelevel.trim(),

        studentsCount:
          Number(this.newGroup.studentsCount),

        schedule:
          this.newGroup.schedule.trim(),

        teacher:
          this.newGroup.teacher.trim()
      };

      this.groups.push(group);
    }

    // Refresh filter options
    this.updateFilterOptions();

    // Refresh table
    this.applyFilters();

    // Close modal
    this.closeModal();
  }

  // =========================================================
  // View Group
  // =========================================================

  viewGroup(group: Group): void {

    this.selectedGroup = group;

    this.isDetailsModalOpen = true;
  }

  // =========================================================
  // Close Details Modal
  // =========================================================

  closeDetailsModal(): void {

    this.isDetailsModalOpen = false;

    this.selectedGroup = null;
  }

  // =========================================================
  // Edit Group
  // =========================================================

  editGroup(group: Group): void {

    this.selectedGroup = group;

    this.isEditMode = true;

    this.newGroup = {

      name: group.name,

      gradelevel:
        group.gradelevel,

      studentsCount:
        group.studentsCount,

      schedule:
        group.schedule,

      teacher:
        group.teacher
    };

    this.isModalOpen = true;
  }

  // =========================================================
  // Delete Group
  // =========================================================

  deleteGroup(group: Group): void {

    const index =
      this.groups.indexOf(group);

    if (index !== -1) {

      this.groups.splice(index, 1);

      this.updateFilterOptions();

      this.applyFilters();
    }
  }
}
<section class="groups-page">

  <!-- ==================== Header ==================== -->
  <div class="groups-header-banner">
    <div class="groups-page__header">

      <div>
        <h2 class="groups-page__title">Groups</h2>

        <p class="groups-page__subtitle">
          Manage and monitor all groups in your learning center.
        </p>
      </div>

      <div class="groups-page__actions">
        <button
          type="button"
          class="btn btn--primary"
          (click)="onAddGroupClick()"
        >
          <svg
            width="16"
            height="16"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
          >
            <path
              d="M12 5v14M5 12h14"
              stroke-linecap="round"
            ></path>
          </svg>

          Add Group
        </button>
      </div>

    </div>
  </div>


  <!-- ==================== Statistics ==================== -->
  <div class="stats-grid">

    <!-- Total Groups -->
    <div class="stat-card">
      <div class="stat-icon stat-icon--blue">
        <i class="fa-solid fa-layer-group"></i>
      </div>

      <div class="stat-content">
        <span class="stat-title">Total Groups</span>
        <strong>{{ groups.length }}</strong>
        <span class="stat-description">All groups</span>
      </div>
    </div>


    <!-- Total Students -->
    <div class="stat-card">
      <div class="stat-icon stat-icon--green">
        <i class="fa-solid fa-user-graduate"></i>
      </div>

      <div class="stat-content">
        <span class="stat-title">Total Students</span>
        <strong>{{ totalStudentsCount }}</strong>
        <span class="stat-description">Across all groups</span>
      </div>
    </div>


    <!-- Grade Levels -->
    <div class="stat-card">
      <div class="stat-icon stat-icon--orange">
        <i class="fa-solid fa-graduation-cap"></i>
      </div>

      <div class="stat-content">
        <span class="stat-title">Grade Levels</span>
        <strong>{{ gradeLevelsCount }}</strong>
        <span class="stat-description">Different levels</span>
      </div>
    </div>


    <!-- Teachers -->
    <div class="stat-card">
      <div class="stat-icon stat-icon--purple">
        <i class="fa-solid fa-chalkboard-user"></i>
      </div>

      <div class="stat-content">
        <span class="stat-title">Teachers</span>
        <strong>{{ teachersCount }}</strong>
        <span class="stat-description">Assigned teachers</span>
      </div>
    </div>

  </div>


  <!-- ==================== Groups List ==================== -->
  <div class="groups-card">

    <!-- Card Header -->
    <div class="groups-card__header">

      <div>
        <h3>Groups List</h3>

        <p>
          {{ filteredGroups.length }} groups found
        </p>
      </div>


      <!-- Filters -->
      <div class="groups-filters">

        <!-- Grade Filter -->
        <select
          [(ngModel)]="selectedGradeLevel"
          (change)="applyFilters()"
        >
          <option value="">All Grade Levels</option>

          <option
            *ngFor="let level of gradeLevels"
            [value]="level"
          >
            {{ level }}
          </option>
        </select>


        <!-- Teacher Filter -->
        <select
          [(ngModel)]="selectedTeacher"
          (change)="applyFilters()"
        >
          <option value="">All Teachers</option>

          <option
            *ngFor="let teacher of teachers"
            [value]="teacher"
          >
            {{ teacher }}
          </option>
        </select>


        <!-- Search -->
        <div class="search-box">

          <svg
            width="16"
            height="16"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
          >
            <circle
              cx="11"
              cy="11"
              r="8"
            ></circle>

            <path
              d="m21 21-4.3-4.3"
            ></path>
          </svg>

          <input
            type="text"
            placeholder="Search groups..."
            [(ngModel)]="searchValue"
            (input)="applyFilters()"
          />

        </div>

      </div>

    </div>


    <!-- ==================== Groups Table ==================== -->
    <div class="table-wrapper">

      <table class="groups-table">

        <thead>
          <tr>
            <th>GROUP</th>
            <th>GRADE LEVEL</th>
            <th>STUDENTS</th>
            <th>SCHEDULE</th>
            <th>TEACHER</th>
            <th>ACTIONS</th>
          </tr>
        </thead>


        <tbody>

          <!-- Group Rows -->
          <tr
            *ngFor="let group of filteredGroups"
          >

            <!-- Group -->
            <td>

              <div class="group-cell">

                <div class="group-avatar">
                  {{ getInitial(group.name) }}
                </div>

                <div class="group-info">
                  <strong>{{ group.name }}</strong>
                  <span>Learning Group</span>
                </div>

              </div>

            </td>


            <!-- Grade Level -->
            <td>
              <span class="grade-badge">
                {{ group.gradelevel }}
              </span>
            </td>


            <!-- Students -->
            <td>
              <div class="students-count">
                <i class="fa-solid fa-user-graduate"></i>
                <strong>{{ group.studentsCount }}</strong>
                <span>Students</span>
              </div>
            </td>


            <!-- Schedule -->
            <td>
              <span class="text-muted">
                {{ group.schedule }}
              </span>
            </td>


            <!-- Teacher -->
            <td>
              <div class="teacher-cell">
                <div class="teacher-avatar">
                  {{ getInitials(group.teacher) }}
                </div>

                <span>
                  {{ group.teacher }}
                </span>
              </div>
            </td>


            <!-- Actions -->
            <td>

              <div class="actions">

                <!-- View -->
                <button
                  type="button"
                  title="View"
                  (click)="viewGroup(group)"
                >
                  <i class="fa-regular fa-eye"></i>
                </button>


                <!-- Edit -->
                <button
                  type="button"
                  title="Edit"
                  (click)="editGroup(group)"
                >
                  <i class="fa-solid fa-pen"></i>
                </button>


                <!-- Delete -->
                <button
                  type="button"
                  title="Delete"
                  (click)="deleteGroup(group)"
                >
                  <i class="fa-regular fa-trash-can"></i>
                </button>

              </div>

            </td>

          </tr>


          <!-- ==================== Empty State ==================== -->
          <tr *ngIf="filteredGroups.length === 0">

            <td
              colspan="6"
              class="empty-state"
            >

              <div class="empty-state__icon">
                <i class="fa-solid fa-layer-group"></i>
              </div>

              <strong>No groups found</strong>

              <span>
                Try changing your search or filters.
              </span>

            </td>

          </tr>

        </tbody>

      </table>

    </div>

  </div>

</section>


<!-- ========================================================= -->
<!-- Add / Edit Group Modal -->
<!-- ========================================================= -->

<div
  class="modal-overlay"
  *ngIf="isModalOpen"
>

  <div class="modal-card">

    <h3>
      {{ isEditMode ? 'Edit Group' : 'New Group' }}
    </h3>


    <!-- Group Name -->
    <div class="form-group">

      <label>Group Name</label>

      <input
        type="text"
        [(ngModel)]="newGroup.name"
        placeholder="Enter group name"
      />

    </div>


    <!-- Grade Level -->
    <div class="form-group">

      <label>Grade Level</label>

      <input
        type="text"
        [(ngModel)]="newGroup.gradelevel"
        placeholder="Enter grade level"
      />

    </div>


    <!-- Students Count -->
    <div class="form-group">

      <label>Students Count</label>

      <input
        type="number"
        [(ngModel)]="newGroup.studentsCount"
        placeholder="Enter students count"
        min="0"
      />

    </div>


    <!-- Schedule -->
    <div class="form-group">

      <label>Schedule</label>

      <input
        type="text"
        [(ngModel)]="newGroup.schedule"
        placeholder="Enter schedule"
      />

    </div>


    <!-- Teacher -->
    <div class="form-group">

      <label>Teacher</label>

      <input
        type="text"
        [(ngModel)]="newGroup.teacher"
        placeholder="Enter teacher name"
      />

    </div>


    <!-- Modal Actions -->
    <div class="modal-actions">

      <button
        type="button"
        class="btn btn--ghost-dark"
        (click)="closeModal()"
      >
        Cancel
      </button>

      <button
        type="button"
        class="btn btn--primary modal-save-btn"
        (click)="saveGroup()"
      >
        {{ isEditMode ? 'Update Group' : 'Save Group' }}
      </button>

    </div>

  </div>

</div>


<!-- ========================================================= -->
<!-- Group Details Modal -->
<!-- ========================================================= -->

<div
  class="modal-overlay"
  *ngIf="isDetailsModalOpen && selectedGroup"
>

  <div class="modal-card">

    <h3>Group Details</h3>


    <div class="group-details">

      <div>
        <strong>Group Name:</strong>
        {{ selectedGroup.name }}
      </div>

      <div>
        <strong>Grade Level:</strong>
        {{ selectedGroup.gradelevel }}
      </div>

      <div>
        <strong>Students Count:</strong>
        {{ selectedGroup.studentsCount }}
      </div>

      <div>
        <strong>Schedule:</strong>
        {{ selectedGroup.schedule }}
      </div>

      <div>
        <strong>Teacher:</strong>
        {{ selectedGroup.teacher }}
      </div>

    </div>


    <!-- Modal Actions -->
    <div class="modal-actions">

      <button
        type="button"
        class="btn btn--primary modal-save-btn"
        (click)="closeDetailsModal()"
      >
        Close
      </button>

    </div>

  </div>

</div>
